    if (!n.a.length) return '[]'
    const pad = '  '.repeat(ind + 1)
    return '[\n' + n.a.map((x) => pad + ser(x, ind + 1)).join(',\n') + '\n' + '  '.repeat(ind) + ']'
  }
  return scalar(n)
}

