const P = (a) => a.join('.').replace(/\.\[/g, '[')

function descend(t, base, names) {
  let cur = t
  for (let i = 0; i < names.length; i++) {
    const n = names[i]
    const ex = cur.m.get(n)
    if (ex === undefined) {
      const nt = table()
      cur.m.set(n, nt)
      cur = nt
    } else if (ex.k === 'table') cur = ex
    else if (ex.k === 'array' && ex.aot) cur = ex.a[ex.a.length - 1]
    else fail(P(base.concat(names.slice(0, i + 1))) + ' is not a table')
  }
  return cur
}

function assign(t, base, names, v) {
  const cur = descend(t, base, names.slice(0, -1))
  const last = names[names.length - 1]
  if (cur.m.has(last)) fail(`key ${P(base.concat(names))} is defined twice`)
  cur.m.set(last, v)
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = table()
  let cur = root
  let curPath = []
  for (let ln = 0; ln < lines.length; ln++) {
    try {
      const L = new Line(lines[ln])
      L.ws()
      if (L.atEnd()) continue
      if (L.ch === '[') {
        const isArr = L.s[L.i + 1] === '['
        L.i += isArr ? 2 : 1
        const names = L.dotted()
        L.ws()
        if (L.ch !== ']') fail('unterminated table header')
        L.i++
        if (isArr) {
          if (L.ch !== ']') fail('unterminated table header')
          L.i++
        }
        if (!L.atEnd()) fail('trailing text after a table header')
        const parent = descend(root, [], names.slice(0, -1))
        const last = names[names.length - 1]
        const ex = parent.m.get(last)
        if (isArr) {
          let arr = ex
          if (ex === undefined) {
            arr = { k: 'array', a: [], aot: true }
            parent.m.set(last, arr)
          } else if (ex.k !== 'array' || !ex.aot) fail(P(names) + ' is not an array of tables')
          const nt = table()
          arr.a.push(nt)
          cur = nt
        } else if (ex === undefined) {
          const nt = table()
          nt.hdr = true
          parent.m.set(last, nt)
          cur = nt
        } else if (ex.k !== 'table') fail(P(names) + ' is not a table')
        else if (ex.hdr) fail('table ' + P(names) + ' is defined twice')
        else {
          ex.hdr = true
          cur = ex
        }
        curPath = names
        continue
      }
      const names = L.dotted()
      L.ws()
      if (L.ch !== '=') fail('expected key = value')
      L.i++
      const v = L.value(curPath.concat(names))
      if (!L.atEnd()) fail('trailing text after a value')
      assign(cur, curPath, names, v)
    } catch (e) {
      if (e instanceof ParseError) e.line = ln + 1
      throw e
    }
  }
  return root
}
