        } else if (ex === undefined) {
          const nt = table()
          nt.hdr = true
          parent.m.set(last, nt)
          cur = nt
        } else if (ex.k !== 'table') fail(P(names) + ' is not a table')
        else if (ex.hdr) fail('table ' + P(names) + ' is defined twice')
        else {
          ex.hdr = true
          cur = ex
        }
        curPath = names
        continue
      }
      const names = L.dotted()
      L.ws()
      if (L.ch !== '=') fail('expected key = value')
      L.i++
      const v = L.value(curPath.concat(names))
      if (!L.atEnd()) fail('trailing text after a value')
      assign(cur, curPath, names, v)
    } catch (e) {
      if (e instanceof ParseError) e.line = ln + 1
      throw e
    }
  }
  return root
}
